<script setup lang="ts">
import { ref } from 'vue'; import AppCard from '../../components/AppCard.vue'; import PrimaryButton from '../../components/PrimaryButton.vue'; import { commerceRepository } from '../../services/api/repositories'; import type { ServicePlan } from '../../types/domain'; import { uniApi as uni } from '../../services/platform/uni'
const plans = ref<ServicePlan[]>([]); const activeLevel = ref('初级'); const levels = ['初级', '高级', '慢病']; commerceRepository.listPlans().then(x => { plans.value = x.filter(p => p.cycle === '月') }); const choose = (plan: ServicePlan) => uni.navigateTo({ url: `/pages/order/confirm?planId=${plan.id}` }); const visiblePlans = () => plans.value.filter(plan => plan.level === activeLevel.value)
</script>
<template><view class="page"><view class="topbar"><text class="back" @click="uni.navigateBack()">‹</text><text class="top-title">正式方案</text><text @click="uni.navigateTo({ url: '/pages/services/addons' })">♧</text></view><view class="tabs"><text v-for="level in levels" :key="level" :class="{ active: activeLevel === level }" @click="activeLevel = level">{{ level }}管理</text></view><AppCard v-for="plan in visiblePlans()" :key="plan.id" class="plan-card"><text class="plan-name">{{ plan.name }}</text><text class="price">¥{{ plan.priceFen / 100 }}<small>/月</small></text><text class="muted">{{ plan.description }}</text><PrimaryButton label="立即购买" @tap="choose(plan)" /></AppCard><AppCard v-if="!visiblePlans().length" class="empty"><text class="muted">该等级暂未发布方案，请选择其他等级。</text></AppCard></view></template>
